save(360,dict(paragraphs=["Shakuntala Gupta writes in Odia and English and has taken part in the literary activities of South Asian Poets of New England, or SAPNE. A report of its sixth annual folk and oral literature festival describes her singing an original poem shaped by the Halia songs of western Odisha’s farmers. That participation places her work in conversation with both written poetry and oral performance.","Her poems here explore the closeness of place, desire and the self. ‘ଆବରଣ’ moves from monsoon expectation into images of vulnerability and unequal power, while the English ‘I don’t find myself’ draws on flowers, trees and the language of love. In ‘ମୋ ଭିତରେ ଗାଆଁଟିଏ’, a village lives within the speaker through courtyards, cattle sheds, trees and weathered doors: memory becomes a place another person is invited to enter."],sources=[source('Lokvani — SAPNE sixth annual folk and oral literature festival','https://www.lokvani.com/lokvani/article.php?article_id=19201','Search-index event report describes exact-name Odisha professor performing own Halia-style poem; matches captured SAPNE connection. Direct open returned internal error.','search_index'),source('SAPNE press release — Voice of the People','https://www.lokvani.com/lokvani/article.php?article_id=19241','Indexed organiser press release lists Shakuntala Gupta among participating poets for November20 2022 meeting.','search_index')],identity_match='Specific SAPNE affiliation, Odisha academic description and original Odia performance bridge external report to captured bilingual poet/faculty biography.',poems_read=[dict(id=460,title='ଆବରଣ',coverage='Full four-stanza original.',basis='Monsoon/yaksha, folded paper/boat, wounds, rule and vulnerability.'),dict(id=574,title='I don`t find myself',coverage='Full original.',basis='Tulips, magnolia, butterfly, chinar, intimacy and self-loss.'),dict(id=628,title='ମୋ ଭିତରେ ଗାଆଁଟିଏ',coverage='Full original.',basis='Village map, shrine, courtyards, cattle, shared doors, absence, trees and inner village.')],limitations=['No independently verified standalone book found; shelf omitted.','Teaching/research at Rourkela remains captured detail; no current institution/appointment added.','Festival report has garbled Odia encoding; no reconstructed title quoted.','Personal relationships, religious identity and exact home village not inferred from poems.','External evidence available through index only.'],research_leads=[],next_action='Independent author/editor review and confirmation of current academic affiliation and bibliography.'))
